class Heap {
  private a: number[] = [];
  constructor(private before: (x: number, y: number) => boolean) {}
  get size(): number { return this.a.length; }
  peek(): number { return this.a[0]; }
  push(x: number): void {
    const a = this.a;
    a.push(x);
    for (let i = a.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      for (let i = 0; ;) {
        const l = 2 * i + 1, r = l + 1;
        let b = i;
        if (l < a.length && this.before(a[l], a[b])) b = l;
        if (r < a.length && this.before(a[r], a[b])) b = r;
        if (b === i) break;
        [a[i], a[b]] = [a[b], a[i]];
        i = b;
      }
    }
    return top;
  }
}

function windowMedians(nums: number[], k: number): number[] {
  // Heaps hold indexes, ordered by (value, index) so every entry is unique.
  const less = (i: number, j: number) => nums[i] < nums[j] || (nums[i] === nums[j] && i < j);
  const lo = new Heap((i, j) => less(j, i)); // max-heap: lower half
  const hi = new Heap(less);                 // min-heap: upper half
  let loLive = 0, hiLive = 0, start = 0;     // indexes below start have left the window
  const clean = (h: Heap) => { while (h.size && h.peek() < start) h.pop(); };
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    if (i >= k) {
      const gone = i - k;
      clean(lo);
      if (!less(lo.peek(), gone)) loLive--; else hiLive--;
      start = gone + 1;
    }
    // Enter through lo, then pass lo's largest live value up to hi: the halves stay split.
    lo.push(i);
    clean(lo);
    hi.push(lo.pop());
    hiLive++;
    while (loLive > hiLive + 1) { clean(lo); hi.push(lo.pop()); loLive--; hiLive++; }
    while (loLive < hiLive) { clean(hi); lo.push(hi.pop()); hiLive--; loLive++; }
    if (i >= k - 1) {
      clean(lo); clean(hi);
      out.push(k % 2 ? nums[lo.peek()] : nums[lo.peek()] / 2 + nums[hi.peek()] / 2);
    }
  }
  return out;
}

